package main

import "fmt"

type EmailNotifier struct{}

func (EmailNotifier) Notify(message string) error {
    fmt.Println(message)
    return nil
}

func SendAll(notifier *EmailNotifier, messages []string) error {
    for _, message := range messages {
        notifier.Notify(message) // TODO: propagate the error
    }
    return nil
}

func main() {
    SendAll(&EmailNotifier{}, []string{"hello"})
}
